package com.example.bandlink.service;
import org.springframework.web.multipart.MultipartFile; import org.springframework.stereotype.Service; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class ImageStorageService {private static final long MAX=5*1024*1024; private static final Set<String> TYPES=Set.of("image/jpeg","image/png","image/webp"); private final Path root=Paths.get(System.getenv().getOrDefault("BANDLINK_UPLOAD_DIR","uploads")).toAbsolutePath().normalize(); public String store(MultipartFile file){if(file==null||file.isEmpty()||file.getSize()>MAX||!TYPES.contains(file.getContentType()))throw new IllegalArgumentException("画像はjpg/png/webp、1枚5MBまでです");try{byte[] data=file.getBytes();byte[] head=java.util.Arrays.copyOf(data,Math.min(12,data.length));if(!valid(file.getContentType(),head))throw new IllegalArgumentException("画像形式を確認できません");Files.createDirectories(root);String ext=switch(file.getContentType()){case "image/jpeg"->".jpg";case "image/png"->".png";default->".webp";};String name=UUID.randomUUID()+ext;Path target=root.resolve(name).normalize();if(!target.startsWith(root))throw new IllegalArgumentException("不正なファイル名です");Files.write(target,data);return "/uploads/"+name;}catch(IOException e){throw new IllegalStateException("画像保存に失敗しました",e);}}private boolean valid(String type,byte[] b){if(type.equals("image/jpeg"))return b.length>2&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;if(type.equals("image/png"))return b.length>8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71;return b.length>12&&b[0]==82&&b[1]==73&&b[2]==70&&b[3]==70&&b[8]==87&&b[9]==69&&b[10]==66&&b[11]==80;}}
